            if val == 'bash':
                sys.stdout.write(COMP_BASH)
            elif val == 'zsh':
                sys.stdout.write(COMP_ZSH)
            elif val == 'fish':
                sys.stdout.write(COMP_FISH)
            elif val == 'elvish':
                sys.stdout.write(COMP_ELVISH)
            elif val == 'powershell':
                sys.stdout.write(COMP_POWERSHELL)
            sys.exit(0)

def parse_args(argv):
    handle_early_completions(argv)
    config = {}
    for k,v in SPEC.items():
        if v.get('multiple'):
            config[k] = []
        else:
            config[k] = v.get('default')
    positional = []
    i = 0
    while i < len(argv):
        arg = argv[i]
        if arg == '--':
            positional.extend(argv[i+1:])
            break
        elif arg.startswith('--'):
            if '=' in arg:
                name, val = arg.split('=',1)
            else:
                name = arg
                val = None
            if name not in LONG_TO_KEY:
                error_exit(f"error: unexpected argument '{name}' found\n\n  tip: to pass '{name}' as a value, use '-- {name}'\n\nUsage: executable [OPTIONS] [PATH]\n\nFor more information, try '--help'.\n")
            key = LONG_TO_KEY[name]
            spec = SPEC[key]
            has = spec['has_value']
            if has == False:
                if val is not None:
                    error_exit(f"error: unexpected value '{val}' for '{name}' found; no more were expected\n\nUsage: executable [OPTIONS] [PATH]\n\nFor more information, try '--help'.\n")
                config[key] = True
                i+=1
            elif has == True:
                if val is None:
                    if i+1 >= len(argv):
                        error_exit(f"error: a value is required for '{name} <{spec['value_name']}>' but none was supplied\n\nFor more information, try '--help'.\n")
                    nxt = argv[i+1]
                    if nxt.startswith('-') and nxt not in ('-','--'):
                        error_exit(f"error: a value is required for '{name} <{spec['value_name']}>' but none was supplied\n\nFor more information, try '--help'.\n")
                    val = nxt
                    i+=2
                else:
                    i+=1
                if 'choices' in spec and val not in spec['choices']:
                    error_exit(f"error: invalid value '{val}' for '{name} <{spec['value_name']}>'\n  [possible values: {', '.join(spec['choices'])}]\n\nFor more information, try '--help'.\n")
                if spec.get('multiple'):
                    config[key].append(val)
                else:
                    if key == 'port':
                        try:
                            int(val)
                        except:
                            error_exit(f"error: invalid value '{val}' for '--port <PORT>': invalid digit found in string\n\nFor more information, try '--help'.\n")
                    config[key] = val
            elif has == 'optional':
                if val is not None:
                    if val == "":
                        config[key] = True
                    else:
                        config[key] = val
                    i+=1
                else:
                    if i+1 < len(argv) and not argv[i+1].startswith('-'):
                        nxt = argv[i+1]
                        if i+1 == len(argv)-1 and (os.path.exists(nxt) or nxt in (".","..")):
                            config[key] = True
                            i+=1
                        else:
                            config[key] = nxt
                            i+=2
                        continue
                    else:
                        config[key] = True
                        i+=1
            else:
                error_exit(f"error: unexpected argument '{arg}' found\n\nFor more information, try '--help'.\n")
        elif arg.startswith('-') and arg != '-':
            j = 1
            extra_consume = 0
            pos = j
            while pos < len(arg):
                c = arg[pos]
                short = '-'+c
                if short not in SHORT_TO_KEY:
                    error_exit(f"error: unexpected argument '{short}' found\n\nUsage: executable [OPTIONS] [PATH]\n\nFor more information, try '--help'.\n")
                key = SHORT_TO_KEY[short]
                spec = SPEC[key]
                has = spec['has_value']
                if has == False:
                    config[key] = True
                    pos += 1
                    continue
                elif has == True:
                    if pos+1 < len(arg):
                        val = arg[pos+1:]
                        if 'choices' in spec and val not in spec['choices']:
                            error_exit(f"error: invalid value '{val}' for '{spec['long']} <{spec['value_name']}>'\n  [possible values: {', '.join(spec['choices'])}]\n\nFor more information, try '--help'.\n")
                        if spec.get('multiple'):
                            config[key].append(val)
                        else:
                            if key == 'port':
                                try:
                                    int(val)
                                except:
                                    error_exit(f"error: invalid value '{val}' for '--port <PORT>': invalid digit found in string\n\nFor more information, try '--help'.\n")
                            config[key] = val
                        pos = len(arg)
                        break
                    else:
                        if i+1 >= len(argv):
                            error_exit(f"error: a value is required for '{short} <{spec['value_name']}>' but none was supplied\n\nFor more information, try '--help'.\n")
                        nxt = argv[i+1]
                        if nxt.startswith('-'):
                            error_exit(f"error: a value is required for '{short} <{spec['value_name']}>' but none was supplied\n\nFor more information, try '--help'.\n")
                        val = nxt
                        if 'choices' in spec and val not in spec['choices']:
                            error_exit(f"error: invalid value '{val}' for '{spec['long']} <{spec['value_name']}>'\n  [possible values: {', '.join(spec['choices'])}]\n\nFor more information, try '--help'.\n")
                        if spec.get('multiple'):
                            config[key].append(val)
                        else:
                            if key == 'port':
                                try:
                                    int(val)
                                except:
                                    error_exit(f"error: invalid value '{val}' for '--port <PORT>': invalid digit found in string\n\nFor more information, try '--help'.\n")
                            config[key] = val
                        extra_consume = 1
                        pos = len(arg)
                        break
                elif has == 'optional':
                    if pos+1 < len(arg):
                        val = arg[pos+1:]
                        config[key] = val if val else True
                        pos = len(arg)
                        break
                    else:
                        if i+1 < len(argv) and not argv[i+1].startswith('-'):
                            nxt = argv[i+1]
                            if i+1 == len(argv)-1 and (os.path.exists(nxt) or nxt in (".","..")):
                                config[key] = True
                            else:
                                config[key] = nxt
                                extra_consume = 1
                        else:
                            config[key] = True
                        pos = len(arg)
                        break
                else:
                    pos+=1
            i += 1 + extra_consume
            continue
        else:
            positional.append(arg)
            i+=1
    if len(positional) > 1:
        error_exit(f"error: unexpected argument '{positional[1]}' found\n\nUsage: executable [OPTIONS] [PATH]\n\nFor more information, try '--help'.\n")
    path = positional[0] if positional else None
    if path is None and 'MINISERVE_PATH' in os.environ and os.environ['MINISERVE_PATH'] != "":
        path = os.environ['MINISERVE_PATH']
    for k,spec in SPEC.items():
        env_name = spec.get('env')
        if env_name and env_name in os.environ and os.environ[env_name] != "":
            env_val = os.environ[env_name]
            cur = config.get(k)
            default = spec.get('default')
            if spec.get('multiple'):
                if len(cur) == 0:
                    config[k] = [env_val] if env_val else []
            else:
                if cur == default:
                    if spec['has_value'] == False:
                        if env_val.lower() not in ("0","false","no","off",""):
                            config[k] = True
                        else:
                            config[k] = False
                    else:
                        if 'choices' in spec and env_val not in spec['choices']:
                            error_exit(f"error: invalid value '{env_val}' for '{spec['long']} <{spec['value_name']}>'\n  [possible values: {', '.join(spec['choices'])}]\n\nFor more information, try '--help'.\n")
                        if k == 'port':
                            try:
                                int(env_val)
                            except:
                                error_exit(f"error: invalid value '{env_val}' for '--port <PORT>': invalid digit found in string\n\nFor more information, try '--help'.\n")
                        config[k] = env_val
    if config.get('random-route'):
        config['route-prefix'] = ''.join(random.choice('0123456789abcdef') for _ in range(6))
    rp = config.get('route-prefix')
    if rp:
        rp = rp.strip()
        if not rp.startswith('/'):
            rp = '/' + rp
        rp = rp.rstrip('/')
        if rp == "":
            rp = "/"
        config['route-prefix'] = rp
    return config, path

def human_size(n):
    if n < 1024:
        return f"{n} B"
    elif n < 1024*1024:
        return f"{n/1024:.1f} KiB"
    elif n < 1024*1024*1024:
        return f"{n/(1024*1024):.1f} MiB"
    else:
        return f"{n/(1024*1024*1024):.1f} GiB"

def exact_size(n):
    return f"{n} B"

def format_date(ts):
    dt = datetime.datetime.fromtimestamp(ts, tz=datetime.timezone.utc)
    return dt.strftime("%Y-%m-%d %H:%M:%S +00:00")

def relative_time(ts):
    now = time.time()
    diff = now - ts
    if diff < 60:
        return "now"
    elif diff < 3600:
        m = int(diff//60)
        return f"{m} minutes ago" if m !=1 else "a minute ago"
    elif diff < 86400:
        h = int(diff//3600)
        return f"{h} hours ago" if h !=1 else "an hour ago"
    elif diff < 86400*30:
        d = int(diff//86400)
        return f"{d} days ago" if d !=1 else "a day ago"
    else:
        return format_date(ts)

def generate_etag(stat):
    try:
        m = int(stat.st_mtime)
        s = stat.st_size
        h = hashlib.md5(f"{m}-{s}-{stat.st_ino}".encode()).hexdigest()[:8]
        return f'"{m:x}:{s:x}:{stat.st_ino:x}:{h}"'
    except:
        return f'"{stat.st_mtime}:{stat.st_size}"'

def parse_auth_entry(entry):
    if ':' not in entry:
        return {'user': entry, 'type':'plain','value':''}
    parts = entry.split(':',2)
    if len(parts) == 2:
        user, pwd = parts
        if pwd == "":
            return {'user': user, 'type':'plain','value':''}
        return {'user': user, 'type':'plain','value': pwd}
    elif len(parts)==3:
        user, method, hashval = parts
        if method in ('sha256','sha512'):
            return {'user': user, 'type':method,'value': hashval.lower()}
        else:
            return {'user': user, 'type':'plain','value': method+":"+hashval}
    return None

def check_auth(auth_header, auth_list):
    if not auth_list:
        return True
    if not auth_header or not auth_header.startswith('Basic '):
        return False
    try:
        b64 = auth_header[6:].strip()
        decoded = base64.b64decode(b64).decode('utf-8', errors='ignore')
        if ':' not in decoded:
            return False
        user, pwd = decoded.split(':',1)
        for entry in auth_list:
            e = parse_auth_entry(entry)
            if e['user'] != user:
                continue
            if e['type'] == 'plain':
                if e['value'] == pwd:
                    return True
            elif e['type'] == 'sha256':
                h = hashlib.sha256(pwd.encode()).hexdigest()
                if h == e['value']:
                    return True
            elif e['type'] == 'sha512':
                h = hashlib.sha512(pwd.encode()).hexdigest()
                if h == e['value']:
                    return True
        return False
    except Exception as e:
        return False

GLOBAL_CONFIG = {}
GLOBAL_BASE = ""
GLOBAL_IS_FILE = False

class Handler(BaseHTTPRequestHandler):
    def log_message(self, format, *args):
        if GLOBAL_CONFIG.get('verbose'):
            sys.stderr.write("%s - - [%s] %s\n" % (self.client_address[0], self.log_date_time_string(), format%args))

    def send_auth_required(self):
        self.send_response(401)
        self.send_header('WWW-Authenticate', 'Basic realm="miniserve"')
        self.send_header('Content-Length','0')
        self.send_header('Date', self.date_time_string())
        self.end_headers()

    def do_AUTH(self):
        auth_list = []
        if GLOBAL_CONFIG.get('auth'):
            val = GLOBAL_CONFIG['auth']
            if isinstance(val, list):
                auth_list.extend(val)
            elif val not in (None, True, False):
                auth_list.append(val)
        if GLOBAL_CONFIG.get('auth-file'):
            try:
                with open(GLOBAL_CONFIG['auth-file'],'r') as f:
                    for line in f:
                        line=line.strip()
                        if line:
                            auth_list.append(line)
            except Exception as e:
                pass
        if not auth_list:
            return True
        auth_list = [a for a in auth_list if isinstance(a, str)]
        if not auth_list:
            return True
        hdr = self.headers.get('Authorization')
        if not check_auth(hdr, auth_list):
            self.send_auth_required()
            return False
        return True

    def handle_route_prefix(self, path):
        rp = GLOBAL_CONFIG.get('route-prefix')
        if rp:
            if path == rp:
                return None, True
            if path == rp + "/":
                return "/", False
            if path.startswith(rp + "/"):
                inner = path[len(rp):]
                if not inner.startswith('/'):
                    inner = '/' + inner
                return inner, False
            else:
                return None, False
        else:
            return path, False

    def serve_internal(self, inner_path):
        if inner_path == "/__miniserve_internal/style.css":
            self.send_response(200)
            self.send_header('Content-Type','text/css')
            self.send_header('Content-Length', str(len(STYLE_CSS)))
            self.send_header('Date', self.date_time_string())
            for h in GLOBAL_CONFIG.get('header') or []:
                if ':' in h:
                    k,v = h.split(':',1)
                    self.send_header(k.strip(), v.strip())
            self.end_headers()
            self.wfile.write(STYLE_CSS)
            return True
        elif inner_path == "/__miniserve_internal/favicon.svg":
            self.send_response(200)
            self.send_header('Content-Type','image/svg+xml')
            self.send_header('Content-Length', str(len(FAVICON_SVG)))
            self.send_header('Date', self.date_time_string())
            for h in GLOBAL_CONFIG.get('header') or []:
                if ':' in h:
                    k,v = h.split(':',1)
                    self.send_header(k.strip(), v.strip())
            self.end_headers()
            self.wfile.write(FAVICON_SVG)
            return True
        elif inner_path == "/__miniserve_internal/api":
            if self.command != "POST":
                self.send_error(405)
                return True
            length = int(self.headers.get('Content-Length',0))
            body = self.rfile.read(length) if length else b""
            try:
                data = json.loads(body.decode('utf-8') if body else "{}")
            except:
                self.send_error(400, "Json deserialize error")
                return True
            if "DirSize" in data:
                dir_path = data["DirSize"]
                rp = GLOBAL_CONFIG.get('route-prefix')
                if rp and dir_path.startswith(rp):
                    dir_path = dir_path[len(rp):]
                    if not dir_path.startswith('/'):
                        dir_path = '/' + dir_path
                fs_path = self.resolve_fs(dir_path)
                if not fs_path or not os.path.isdir(fs_path):
                    self.send_response(404)
                    self.send_header('Content-Length','0')
                    self.end_headers()
                    return True
                total = 0
                for root, dirs, files in os.walk(fs_path):
                    for f in files:
                        fp = os.path.join(root,f)
                        try:
                            if GLOBAL_CONFIG.get('no-symlinks') and os.path.islink(fp):
                                continue
                            total += os.path.getsize(fp)
                        except:
                            pass
                size_str = human_size(total) if GLOBAL_CONFIG.get('size-display') != 'exact' else exact_size(total)
                self.send_response(200)
                self.send_header('Content-Type','text/plain')
                body_bytes = size_str.encode()
                self.send_header('Content-Length', str(len(body_bytes)))
                self.send_header('Date', self.date_time_string())
                self.end_headers()
                self.wfile.write(body_bytes)
                return True
            else:
                self.send_response(400)
                self.send_header('Content-Type','text/html')
                msg = f"Json deserialize error: unknown variant `{list(data.keys())[0] if data else ''}`, expected `DirSize` at line 1 column 8"
                html_body = self.error_html(400, "Bad Request", msg)
                body_bytes = html_body.encode()
                self.send_header('Content-Length', str(len(body_bytes)))
                self.send_header('Date', self.date_time_string())
                self.end_headers()
                self.wfile.write(body_bytes)
                return True
        return False

    def resolve_fs(self, url_path):
        if GLOBAL_IS_FILE:
            return GLOBAL_BASE
        rel = url_path.lstrip('/')
        rel = unquote(rel)
        base = GLOBAL_BASE
        fs = os.path.join(base, rel)
        fs = os.path.normpath(fs)
        try:
            common = os.path.commonpath([fs, base])
        except ValueError:
            return None
        if common != base:
            return None
        return fs

    def error_html(self, code, title, msg):
        rp = GLOBAL_CONFIG.get('route-prefix') or ""
        prefix = rp if rp else ""
        head = f'''<!DOCTYPE html><html><head><meta charset="utf-8"><meta http-equiv="X-UA-Compatible" content="IE=edge"><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="color-scheme" content="dark light"><link rel="icon" type="image/svg+xml" href="{prefix}/__miniserve_internal/favicon.svg"><link rel="stylesheet" href="{prefix}/__miniserve_internal/style.css"><title>{code} {title}</title><script>
                    // updates the color scheme by setting the theme data attribute
                    // on body and saving the new theme to local storage
                    function updateColorScheme(name) {{
                        if (name && name != "default") {{
                            localStorage.setItem('theme', name);
                            document.body.setAttribute("data-theme", name)
                        }} else {{
                            localStorage.removeItem('theme');
                            document.body.removeAttribute("data-theme")
                        }}
                    }}

                    // read theme from local storage and apply it to body
                    function loadColorScheme() {{
                        var name = localStorage.getItem('theme');
                        updateColorScheme(name);
                    }}

                    // load saved theme on page load
                    addEventListener("load", loadColorScheme);
                    // load saved theme when local storage is changed (synchronize between tabs)
                    addEventListener("storage", loadColorScheme);
                </script><script>const API_ROUTE = '{prefix}/__miniserve_internal/api';
                    let dirSizeCache = {{}};

                    // Query the directory size from the miniserve API
                    function fetchDirSize(dir) {{
                        return fetch(API_ROUTE, {{
                            headers: {{
                                'Accept': 'application/json',
                                'Content-Type': 'application/json'
                            }},
                            method: 'POST',
                            body: JSON.stringify({{
                                DirSize: dir
                            }})
                        }}).then(resp => resp.ok ? resp.text() : "~")
                    }}

                    function updateSizeCells() {{
                        const directoryCells = document.querySelectorAll('tr.entry-type-directory .size-cell');

                        directoryCells.forEach(cell => {{
                            // Get the dir from the sibling anchor tag.
                            const href = cell.parentNode.querySelector('a').href;
                            const target = new URL(href).pathname;

                            // First check our local cache
                            if (target in dirSizeCache) {{
                                cell.dataset.size = dirSizeCache[target];
                            }} else {{
                                fetchDirSize(target).then(dir_size => {{
                                    cell.dataset.size = dir_size;
                                    dirSizeCache[target] = dir_size;
                                }})
                                .catch(error => console.error("Error fetching dir size:", error));
                            }}
                        }})
                    }}
                    setInterval(updateSizeCells, 1000);
                </script></head><body><div class="error"><p>{code} {title}</p><p>{html.escape(msg)}</p><div class="error-nav"><a class="error-back" href="{prefix}/">Go back to file listing</a></div><p class="footer"><div class="version"><a href="https://github.com/svenstaro/miniserve">miniserve</a>/0.32.0</div></p></div></body></html>'''
        return head

    def send_error_html(self, code, title, msg=""):
        body = self.error_html(code, title, msg)
        body_bytes = body.encode()
        self.send_response(code)
        self.send_header('Content-Type','text/html')
        self.send_header('Content-Length', str(len(body_bytes)))
        self.send_header('Date', self.date_time_string())
        for h in GLOBAL_CONFIG.get('header') or []:
            if ':' in h:
                k,v = h.split(':',1)
                self.send_header(k.strip(), v.strip())
        self.end_headers()
        if self.command != "HEAD":
            self.wfile.write(body_bytes)

    def do_GET(self):
        self.handle_request("GET")
    def do_HEAD(self):
        self.handle_request("HEAD")
    def do_POST(self):
        self.handle_request("POST")
    def do_PROPFIND(self):
        self.handle_request("PROPFIND")
    def do_DELETE(self):
        self.handle_request("DELETE")

    def handle_request(self, method):
        if not self.do_AUTH():
            return
        parsed = urlparse(self.path)
        path = parsed.path
        query = parse_qs(parsed.query)
        inner, redirect = self.handle_route_prefix(path)
        if redirect:
            rp = GLOBAL_CONFIG.get('route-prefix')
            self.send_response(301)
            self.send_header('Location', rp + "/")
            self.send_header('Content-Length','0')
            self.send_header('Date', self.date_time_string())
            self.end_headers()
            return
        if inner is None:
            self.send_error_html(404, "Not Found", "Not Found")
            return
        if inner.startswith("/__miniserve_internal"):
            if self.serve_internal(inner):
                return
            else:
                self.send_error_html(404, "Not Found")
                return
        if method == "POST" and inner.startswith("/upload"):
            self.handle_upload(parsed, inner)
            return
        if method == "POST" and inner.startswith("/rm"):
            self.handle_rm(parsed, inner)
            return
        if method == "PROPFIND":
            self.handle_propfind(inner, query)
            return
        if method in ("GET","HEAD"):
            self.handle_get_head(inner, query, method)
            return
        self.send_error_html(405, "Method Not Allowed")

    def handle_upload(self, parsed, inner):
        qs = parse_qs(parsed.query)
        target_param = qs.get('path', ['/'])[0]
        upload_cfg = GLOBAL_CONFIG.get('upload-files')
        if upload_cfg is None:
            self.send_response(403)
            self.send_header('Content-Type','text/plain; charset=utf-8')
            body=b"Upload not allowed to this directory"
            self.send_header('Content-Length', str(len(body)))
            self.send_header('Date', self.date_time_string())
            self.end_headers()
            self.wfile.write(body)
            return
        if not target_param.startswith('/'):
            target_param = '/' + target_param
        target_fs = self.resolve_fs(target_param)
        if not target_fs:
            self.send_error_html(404, "Not Found")
            return
        if isinstance(upload_cfg, str) and upload_cfg not in (True,):
            allowed = upload_cfg
            if not allowed.startswith('/'):
                allowed = '/' + allowed
            if not (target_param == allowed or target_param.startswith(allowed.rstrip('/') + '/')):
                self.send_response(403)
                self.send_header('Content-Type','text/plain; charset=utf-8')
                body=b"Upload not allowed to this directory"
                self.send_header('Content-Length', str(len(body)))
                self.send_header('Date', self.date_time_string())
                self.end_headers()
                self.wfile.write(body)
                return
        ctype = self.headers.get('Content-Type','')
        if 'multipart/form-data' not in ctype:
            self.send_response(400)
            body=b"Failed to process multipart request\ncaused by: Multipart stream is incomplete"
            self.send_header('Content-Type','text/plain')
            self.send_header('Content-Length', str(len(body)))
            self.send_header('Date', self.date_time_string())
            self.end_headers()
            self.wfile.write(body)
            return
        m = re.search(r'boundary=([^;\s]+)', ctype)
        if not m:
            self.send_response(400)
            body=b"Failed to process multipart request"
            self.send_header('Content-Length', str(len(body)))
            self.end_headers()
            self.wfile.write(body)
            return
        boundary = m.group(1).strip('"')
        length = int(self.headers.get('Content-Length',0))
        body = self.rfile.read(length) if length else b""
        delim = ('--' + boundary).encode()
        parts = body.split(delim)
        mkdir_done = False
        file_done = False
        for part in parts:
            if not part or part == b'--' or part == b'--\r\n':
                continue
            if part.startswith(b'\r\n'):
                part = part[2:]
            if part.endswith(b'\r\n'):
                part = part[:-2]
            if not part:
                continue
            if b'\r\n\r\n' not in part:
                continue
            header_block, content = part.split(b'\r\n\r\n',1)
            if content.endswith(b'\r\n'):
                content = content[:-2]
            headers = header_block.decode('utf-8', errors='ignore')
            cd_match = re.search(r'Content-Disposition:.*name="([^"]+)".*filename="([^"]*)"', headers, re.I)
            if cd_match:
                name = cd_match.group(1)
                filename = cd_match.group(2)
                if filename:
                    filename = os.path.basename(filename)
                    if not filename:
                        continue
                    dest = os.path.join(target_fs, filename)
                    if not os.path.isdir(target_fs):
                        self.send_response(400)
                        body=b"Target is not a directory"
                        self.send_header('Content-Length', str(len(body)))
                        self.end_headers()
                        self.wfile.write(body)
                        return
                    on_dup = GLOBAL_CONFIG.get('on-duplicate-files') or 'error'
                    if os.path.exists(dest):
                        if on_dup == 'error':
                            self.send_response(409)
                            self.send_header('Content-Type','text/plain; charset=utf-8')
                            body=b"File already exists, and the on_duplicate_files option is set to error out"
                            self.send_header('Content-Length', str(len(body)))
                            self.send_header('Date', self.date_time_string())
                            self.end_headers()
                            self.wfile.write(body)
                            return
                        elif on_dup == 'overwrite':
                            pass
                        elif on_dup == 'rename':
                            base, ext = os.path.splitext(filename)
                            counter = 1
                            while os.path.exists(dest):
                                newname = f"{base}-{counter}{ext}"
                                dest = os.path.join(target_fs, newname)
                                counter+=1
                                if counter>1000:
                                    break
                    temp_dir = GLOBAL_CONFIG.get('temp-directory')
                    try:
                        os.makedirs(os.path.dirname(dest), exist_ok=True)
                        if temp_dir:
                            import tempfile
                            os.makedirs(temp_dir, exist_ok=True)
                            fd, tmp_path = tempfile.mkstemp(dir=temp_dir)
                            os.write(fd, content)
                            os.close(fd)
                            shutil.move(tmp_path, dest)
                        else:
                            with open(dest,'wb') as f:
                                f.write(content)
                        chmod_val = GLOBAL_CONFIG.get('chmod')
                        if chmod_val:
                            try:
                                mode = int(chmod_val, 8)
                                os.chmod(dest, mode)
                            except:
                                pass
                        file_done = True
                    except Exception as e:
                        self.send_response(500)
                        body=str(e).encode()
                        self.send_header('Content-Length', str(len(body)))
                        self.end_headers()
                        self.wfile.write(body)
                        return
                else:
                    if name == 'mkdir':
                        dirname = content.decode('utf-8', errors='ignore').strip()
                        dirname = os.path.basename(dirname)
                        if not dirname or '/' in dirname or '\\' in dirname:
                            self.send_response(400)
                            body=b"Invalid directory name"
                            self.send_header('Content-Length', str(len(body)))
                            self.end_headers()
                            self.wfile.write(body)
                            return
                        dest = os.path.join(target_fs, dirname)
                        try:
                            os.makedirs(dest, exist_ok=False)
                            mkdir_done = True
                        except FileExistsError:
                            self.send_response(400)
                            body=b"Directory already exists"
                            self.send_header('Content-Length', str(len(body)))
                            self.end_headers()
                            self.wfile.write(body)
                            return
                        except Exception as e:
                            self.send_response(500)
                            body=str(e).encode()
                            self.send_header('Content-Length', str(len(body)))
                            self.end_headers()
                            self.wfile.write(body)
                            return
            else:
                cd2 = re.search(r'name="([^"]+)"', headers)
                if cd2:
                    name = cd2.group(1)
                    if name == 'mkdir':
                        dirname = content.decode('utf-8', errors='ignore').strip()
                        dirname = os.path.basename(dirname)
                        if not dirname:
                            continue
                        dest = os.path.join(target_fs, dirname)
                        try:
                            os.makedirs(dest, exist_ok=False)
                            mkdir_done = True
                        except FileExistsError:
                            self.send_response(400)
                            body=b"Directory already exists"
                            self.send_header('Content-Length', str(len(body)))
                            self.end_headers()
                            self.wfile.write(body)
                            return
                        except Exception as e:
                            self.send_response(500)
                            body=str(e).encode()
                            self.send_header('Content-Length', str(len(body)))
                            self.end_headers()
                            self.wfile.write(body)
                            return
        rp = GLOBAL_CONFIG.get('route-prefix') or ""
        location = rp + target_param
        self.send_response(303)
        self.send_header('Location', location)
        self.send_header('Content-Length','0')
        self.send_header('Date', self.date_time_string())
        self.end_headers()

    def handle_rm(self, parsed, inner):
        qs = parse_qs(parsed.query)
        target_param = qs.get('path',[''])[0]
        if not target_param:
            self.send_error_html(400, "Bad Request", "Missing path")
            return
        if not target_param.startswith('/'):
            target_param = '/' + target_param
        rm_cfg = GLOBAL_CONFIG.get('rm-files')
        if rm_cfg is None:
            self.send_response(403)
            body=b"Deletion not allowed"
            self.send_header('Content-Length', str(len(body)))
            self.end_headers()
            self.wfile.write(body)
            return
        if isinstance(rm_cfg, str) and rm_cfg not in (True,):
            allowed = rm_cfg
            if not allowed.startswith('/'):
                allowed = '/' + allowed
            if not (target_param == allowed or target_param.startswith(allowed.rstrip('/') + '/')):
                self.send_response(403)
                body=b"Deletion not allowed to this directory"
                self.send_header('Content-Length', str(len(body)))
                self.end_headers()
                self.wfile.write(body)
                return
        target_fs = self.resolve_fs(target_param)
        if not target_fs or not os.path.exists(target_fs):
            self.send_error_html(404, "Not Found")
            return
        try:
            if os.path.isdir(target_fs) and not os.path.islink(target_fs):
                shutil.rmtree(target_fs)
            else:
                os.remove(target_fs)
        except Exception as e:
            self.send_response(500)
            body=str(e).encode()
            self.send_header('Content-Length', str(len(body)))
            self.end_headers()
            self.wfile.write(body)
            return
        parent = os.path.dirname(target_param.rstrip('/'))
        if not parent:
            parent = '/'
        if not parent.startswith('/'):
            parent = '/' + parent
        rp = GLOBAL_CONFIG.get('route-prefix') or ""
        location = rp + parent
        if not location.endswith('/'):
            location += '/'
        self.send_response(303)
        self.send_header('Location', location)
        self.send_header('Content-Length','0')
        self.send_header('Date', self.date_time_string())
        self.end_headers()

    def handle_propfind(self, inner, query):
        if not GLOBAL_CONFIG.get('enable-webdav'):
            self.send_error_html(404, "Not Found")
            return
        fs_path = self.resolve_fs(inner)
        if not fs_path or not os.path.exists(fs_path):
            self.send_error_html(404, "Not Found")
            return
        depth = self.headers.get('Depth','infinity')
        base_href = inner
        if os.path.isdir(fs_path) and not base_href.endswith('/'):
            base_href += '/'
        xml_parts = ['<?xml version="1.0" encoding="utf-8"?><D:multistatus xmlns:D="DAV:">']
        def add_response(href, fs):
            try:
                st = os.stat(fs)
                is_dir = os.path.isdir(fs)
                ctime = datetime.datetime.fromtimestamp(st.st_ctime, tz=datetime.timezone.utc).strftime("%Y-%m-%dT%H:%M:%SZ")
                mtime = datetime.datetime.fromtimestamp(st.st_mtime, tz=datetime.timezone.utc).strftime("%a, %d %b %Y %H:%M:%S GMT")
                ctype = "httpd/unix-directory" if is_dir else (mimetypes.guess_type(fs)[0] or "application/octet-stream")
                etag = generate_etag(st)
                length = "" if is_dir else str(st.st_size)
                res_type = "<D:collection></D:collection>" if is_dir else ""
                href_esc = html.escape(href)
                xml_parts.append(f'<D:response><D:href>{href_esc}</D:href><D:propstat><D:prop><D:creationdate>{ctime}</D:creationdate>')
                if not is_dir:
                    xml_parts.append(f'<D:getcontentlength>{length}</D:getcontentlength>')
                xml_parts.append(f'<D:getcontenttype>{ctype}</D:getcontenttype><D:getetag>{etag}</D:getetag><D:getlastmodified>{mtime}</D:getlastmodified><D:lockdiscovery></D:lockdiscovery><D:resourcetype>{res_type}</D:resourcetype><D:supportedlock></D:supportedlock></D:prop><D:status>HTTP/1.1 200 OK</D:status></D:propstat></D:response>')
            except Exception as e:
                pass
        add_response(base_href, fs_path)
        if os.path.isdir(fs_path) and depth != "0":
            try:
                entries = os.listdir(fs_path)
                for name in entries:
                    if not GLOBAL_CONFIG.get('hidden') and name.startswith('.'):
                        continue
                    if GLOBAL_CONFIG.get('no-symlinks') and os.path.islink(os.path.join(fs_path, name)):
                        continue
                    child_fs = os.path.join(fs_path, name)
                    child_href = base_href.rstrip('/') + '/' + urllib.parse.quote(name)
                    if os.path.isdir(child_fs):
                        child_href += '/'
                    add_response(child_href, child_fs)
            except:
                pass
        xml_parts.append('</D:multistatus>')
        body = ''.join(xml_parts).encode('utf-8')
        self.send_response(207)
        self.send_header('Content-Type','application/xml; charset=utf-8')
        self.send_header('Content-Length', str(len(body)))
        self.send_header('Date', self.date_time_string())
        self.end_headers()
        self.wfile.write(body)

    def handle_get_head(self, inner, query, method):
        if 'download' in query:
            dl = query['download'][0]
            if dl in ('tar','tar_gz','targz','zip'):
                if dl == 'tar' and not GLOBAL_CONFIG.get('enable-tar'):
                    pass
                elif dl in ('tar_gz','targz') and not GLOBAL_CONFIG.get('enable-tar-gz'):
                    pass
                elif dl == 'zip' and not GLOBAL_CONFIG.get('enable-zip'):
                    pass
                else:
                    fs_path = self.resolve_fs(inner)
                    if not fs_path:
                        self.send_error_html(404, "Not Found")
                        return
                    if os.path.isfile(fs_path):
                        self.serve_file(fs_path, method)
                        return
                    base_name = os.path.basename(os.path.normpath(fs_path)) if fs_path != GLOBAL_BASE else os.path.basename(os.path.normpath(GLOBAL_BASE))
                    if not base_name:
                        base_name = "archive"
                    if dl == 'zip':
                        mem = io.BytesIO()
                        with zipfile.ZipFile(mem, 'w', zipfile.ZIP_DEFLATED) as z:
                            for root, dirs, files in os.walk(fs_path):
                                dirs[:] = [d for d in dirs if (GLOBAL_CONFIG.get('hidden') or not d.startswith('.')) and not (GLOBAL_CONFIG.get('no-symlinks') and os.path.islink(os.path.join(root,d)))]
                                for f in files:
                                    if not GLOBAL_CONFIG.get('hidden') and f.startswith('.'):
                                        continue
                                    fp = os.path.join(root,f)
                                    if GLOBAL_CONFIG.get('no-symlinks') and os.path.islink(fp):
                                        continue
                                    arcname = os.path.relpath(fp, os.path.dirname(fs_path)) if fs_path != GLOBAL_BASE else os.path.relpath(fp, GLOBAL_BASE)
                                    z.write(fp, arcname)
                        data = mem.getvalue()
                        self.send_response(200)
                        self.send_header('Content-Type','application/zip')
                        self.send_header('Content-Disposition', f'attachment; filename="{base_name}.zip"')
                        self.send_header('Content-Length', str(len(data)))
                        self.send_header('Date', self.date_time_string())
                        for h in GLOBAL_CONFIG.get('header') or []:
                            if ':' in h:
                                k,v = h.split(':',1)
                                self.send_header(k.strip(), v.strip())
                        self.end_headers()
                        if method != "HEAD":
                            self.wfile.write(data)
                        return
                    elif dl in ('tar','tar_gz','targz'):
                        mem = io.BytesIO()
                        mode = 'w:gz' if dl in ('tar_gz','targz') else 'w'
                        with tarfile.open(fileobj=mem, mode=mode) as tar:
                            for root, dirs, files in os.walk(fs_path):
                                dirs[:] = [d for d in dirs if (GLOBAL_CONFIG.get('hidden') or not d.startswith('.')) and not (GLOBAL_CONFIG.get('no-symlinks') and os.path.islink(os.path.join(root,d)))]
                                for f in files:
                                    if not GLOBAL_CONFIG.get('hidden') and f.startswith('.'):
                                        continue
                                    fp = os.path.join(root,f)
                                    if GLOBAL_CONFIG.get('no-symlinks') and os.path.islink(fp):
                                        continue
                                    arcname = os.path.relpath(fp, os.path.dirname(fs_path)) if fs_path != GLOBAL_BASE else os.path.relpath(fp, GLOBAL_BASE)
                                    tar.add(fp, arcname=arcname)
                        data = mem.getvalue()
                        self.send_response(200)
                        if dl in ('tar_gz','targz'):
                            self.send_header('Content-Type','application/gzip')
                            self.send_header('Content-Disposition', f'attachment; filename="{base_name}.tar.gz"')
                        else:
                            self.send_header('Content-Type','application/x-tar')
                            self.send_header('Content-Disposition', f'attachment; filename="{base_name}.tar"')
                        self.send_header('Content-Length', str(len(data)))
                        self.send_header('Date', self.date_time_string())
                        for h in GLOBAL_CONFIG.get('header') or []:
                            if ':' in h:
                                k,v = h.split(':',1)
                                self.send_header(k.strip(), v.strip())
                        self.end_headers()
                        if method != "HEAD":
                            self.wfile.write(data)
                        return
        is_raw = 'raw' in query
        if GLOBAL_IS_FILE:
            fs_path = GLOBAL_BASE
            self.serve_file(fs_path, method)
            return
        fs_path = self.resolve_fs(inner)
        if fs_path is None:
            self.send_error_html(404, "Not Found")
            return
        if not os.path.exists(fs_path) and GLOBAL_CONFIG.get('pretty-urls'):
            alt = fs_path + ".html"
            if os.path.isfile(alt):
                self.serve_file(alt, method)
                return
        if not os.path.exists(fs_path) and GLOBAL_CONFIG.get('spa') and GLOBAL_CONFIG.get('index'):
            index_path = os.path.join(GLOBAL_BASE, GLOBAL_CONFIG['index'])
            if os.path.isfile(index_path):
                self.serve_file(index_path, method)
                return
        if not os.path.exists(fs_path):
            self.send_error_html(404, "Not Found")
            return
        if GLOBAL_CONFIG.get('no-symlinks') and os.path.islink(fs_path):
            self.send_error_html(404, "Not Found")
            return
        if os.path.isdir(fs_path):
            if not inner.endswith('/'):
                rp = GLOBAL_CONFIG.get('route-prefix') or ""
                location = rp + inner + "/"
                if self.path.find('?') != -1:
                    location += "?" + self.path.split('?',1)[1]
                self.send_response(301)
                self.send_header('Location', location)
                self.send_header('Content-Length','0')
                self.send_header('Date', self.date_time_string())
                self.end_headers()
                return
            idx_name = GLOBAL_CONFIG.get('index')
            if idx_name:
                idx_path = os.path.join(fs_path, idx_name)
                if os.path.isfile(idx_path):
                    if not (GLOBAL_CONFIG.get('no-symlinks') and os.path.islink(idx_path)):
                        self.serve_file(idx_path, method)
                        return
            if GLOBAL_CONFIG.get('disable-indexing'):
                self.send_error_html(404, "Not Found")
                return
            self.serve_directory(fs_path, inner, query, method, is_raw)
            return
        else:
            self.serve_file(fs_path, method)
            return

    def serve_file(self, fs_path, method):
        try:
            st = os.stat(fs_path)
        except:
            self.send_error_html(404, "Not Found")
            return
        ctype, _ = mimetypes.guess_type(fs_path)
        if ctype is None:
            ctype = 'application/octet-stream'
        if ctype.startswith('text/'):
            ctype += '; charset=utf-8'
        etag = generate_etag(st)
        last_mod = datetime.datetime.fromtimestamp(st.st_mtime, tz=datetime.timezone.utc).strftime("%a, %d %b %Y %H:%M:%S GMT")
        inm = self.headers.get('If-None-Match')
        if inm and inm == etag:
            self.send_response(304)
            self.send_header('ETag', etag)
            self.send_header('Date', self.date_time_string())
            self.end_headers()
            return
        ims = self.headers.get('If-Modified-Since')
        if ims:
            try:
                ims_dt = datetime.datetime.strptime(ims, "%a, %d %b %Y %H:%M:%S %Z")
                if int(st.st_mtime) <= int(ims_dt.timestamp()):
                    self.send_response(304)
                    self.send_header('ETag', etag)
                    self.send_header('Date', self.date_time_string())
                    self.end_headers()
                    return
            except:
                pass
        range_header = self.headers.get('Range')
        file_size = st.st_size
        start = 0
        end = file_size -1
        status = 200
        if range_header and range_header.startswith('bytes='):
            try:
                rang = range_header[6:].strip()
                if '-' in rang:
                    s_str, e_str = rang.split('-',1)
                    if s_str == "":
                        suffix = int(e_str)
                        start = file_size - suffix
                        if start <0: start=0
                    elif e_str == "":
                        start = int(s_str)
                    else:
                        start = int(s_str)
                        end = int(e_str)
                    if start >= file_size:
                        self.send_response(416)
                        self.send_header('Content-Range', f'bytes */{file_size}')
                        self.end_headers()
                        return
                    if end >= file_size:
                        end = file_size-1
                    status = 206
            except:
                pass
        try:
            with open(fs_path,'rb') as f:
                if status == 206:
                    f.seek(start)
                    to_read = end - start +1
                    data = f.read(to_read)
                else:
                    data = f.read()
        except Exception as e:
            self.send_error_html(500, "Internal Server Error", str(e))
            return
        accept_enc = self.headers.get('Accept-Encoding','')
        use_gzip = False
        if GLOBAL_CONFIG.get('compress-response') and 'gzip' in accept_enc:
            data = gzip.compress(data)
            use_gzip = True
        self.send_response(status)
        self.send_header('Content-Type', ctype)
        disposition = f'inline; filename="{os.path.basename(fs_path)}"'
        self.send_header('Content-Disposition', disposition)
        self.send_header('Accept-Ranges','bytes')
        self.send_header('ETag', etag)
        self.send_header('Last-Modified', last_mod)
        if status == 206:
            self.send_header('Content-Range', f'bytes {start}-{end}/{file_size}')
            self.send_header('Content-Length', str(len(data)))
        else:
            self.send_header('Content-Length', str(len(data)))
        if use_gzip:
            self.send_header('Content-Encoding','gzip')
        self.send_header('Date', self.date_time_string())
        for h in GLOBAL_CONFIG.get('header') or []:
            if ':' in h:
                k,v = h.split(':',1)
                self.send_header(k.strip(), v.strip())
        self.end_headers()
        if method != "HEAD":
            self.wfile.write(data)

    def serve_directory(self, fs_path, url_path, query, method, is_raw):
        sort_method = query.get('sort',[GLOBAL_CONFIG.get('default-sorting-method') or 'name'])[0]
        sort_order = query.get('order',[GLOBAL_CONFIG.get('default-sorting-order') or 'desc'])[0]
        if sort_method not in ('name','size','date'):
            sort_method = GLOBAL_CONFIG.get('default-sorting-method') or 'name'
        if sort_order not in ('asc','desc'):
            sort_order = GLOBAL_CONFIG.get('default-sorting-order') or 'desc'
        try:
            entries = os.scandir(fs_path)
        except:
            self.send_error_html(500, "Internal Server Error")
            return
        items = []
        for e in entries:
            if not GLOBAL_CONFIG.get('hidden') and e.name.startswith('.'):
                continue
            if GLOBAL_CONFIG.get('no-symlinks') and e.is_symlink():
                continue
            try:
                st = e.stat(follow_symlinks= not GLOBAL_CONFIG.get('no-symlinks'))
                is_dir = e.is_dir(follow_symlinks= not GLOBAL_CONFIG.get('no-symlinks'))
                items.append((e.name, e.path, is_dir, st))
            except:
                continue
        dirs_first = GLOBAL_CONFIG.get('dirs-first')
        def sort_key(x):
            name, path, is_dir, st = x
            if sort_method == 'name':
                k = name.lower()
            elif sort_method == 'size':
                k = st.st_size if not is_dir else 0
            elif sort_method == 'date':
                k = st.st_mtime
            else:
                k = name.lower()
            return k
        if dirs_first:
            dirs = [x for x in items if x[2]]
            files = [x for x in items if not x[2]]
            dirs.sort(key=sort_key, reverse=(sort_order=='desc'))
            files.sort(key=sort_key, reverse=(sort_order=='desc'))
            items = dirs + files
        else:
            items.sort(key=sort_key, reverse=(sort_order=='desc'))
        rp = GLOBAL_CONFIG.get('route-prefix') or ""
        host = self.headers.get('Host', 'localhost')
        title_val = GLOBAL_CONFIG.get('title') or host
        size_display = GLOBAL_CONFIG.get('size-display') or 'human'
        external = GLOBAL_CONFIG.get('file-external-url')
        qs_str = ""
        qs_str_escaped = ""
        if 'sort' in query or 'order' in query:
            qs_parts = []
            if 'sort' in query:
                qs_parts.append(f"sort={query['sort'][0]}")
            if 'order' in query:
                qs_parts.append(f"order={query['order'][0]}")
            if 'raw' in query:
                qs_parts.append(f"raw={query['raw'][0]}")
            qs_str = "?" + "&".join(qs_parts)
            qs_str_escaped = qs_str.replace("&","&amp;")
        rows = []
        for name, fpath, is_dir, st in items:
            quoted = urllib.parse.quote(name)
            if is_dir:
                href = rp + url_path.rstrip('/') + '/' + quoted + '/' + qs_str
                href = re.sub(r'//+', '/', href)
                href_esc = href.replace("&","&amp;")
                display = html.escape(name) + "/"
                row = f'<tr class="entry-type-directory"><td><p><a class="directory" href="{href_esc}">{display}</a></p></td><td class="size-cell"></td><td class="date-cell"><span>{format_date(st.st_mtime)}</span><span class="history">{relative_time(st.st_mtime)}</span></td>'
                if GLOBAL_CONFIG.get('rm-files') is not None:
